// The generated sync_state table is a separate projection: clearing one must
// not touch the other. This is why the windowed bookmark lives in its own
// table — earliest_day costs a multi-year re-walk to rebuild.
func TestGarminSeriesState_SurvivesAGeneratedSyncCursorClear(t *testing.T) {
	db := newSeriesTestStore(t)
	if err := db.SaveGarminSeriesState(GarminSeriesState{
		Series: "steps", LastCompleteDay: "2026-09-07", EarliestDay: "2020-07-06", TotalRows: 2251,
	}); err != nil {
		t.Fatalf("save: %v", err)
	}
	if err := db.SaveSyncState("steps", "2026-09-07", 2251); err != nil {
		t.Fatalf("mirror: %v", err)
	}
	if err := db.ClearSyncCursors(); err != nil {
		t.Fatalf("clear: %v", err)
	}
	st, err := db.GetGarminSeriesState("steps")
	if err != nil {
		t.Fatalf("get after clear: %v", err)
	}
	if st.EarliestDay != "2020-07-06" {
		t.Fatalf("earliest_day = %q after a generated cursor clear; the windowed bookmark must survive it", st.EarliestDay)
	}
}

func TestUpsertKeyedBatch_StoresUnderTheCallerSuppliedID(t *testing.T) {
	db := newSeriesTestStore(t)
	rows := []KeyedRow{
		{ID: "2026-09-06", Data: json.RawMessage(`{"calendarDate":"2026-09-06","totalSteps":8000,"stepGoal":7500}`)},
		{ID: "2026-09-07", Data: json.RawMessage(`{"calendarDate":"2026-09-07","totalSteps":9100,"stepGoal":7500}`)},
	}
	stored, skipped, err := db.UpsertKeyedBatch("steps", rows)
	if err != nil {
		t.Fatalf("upsert: %v", err)
	}
	if stored != 2 || skipped != 0 {
		t.Fatalf("stored=%d skipped=%d, want 2/0", stored, skipped)
	}
	if _, err := db.Get("steps", "2026-09-06"); err != nil {
		t.Fatalf("row not stored under its calendar-date key: %v", err)
	}
	// The typed projection fires for a resource that has a typed table, so
	// SQL and analytics readers see the day too.
	var n int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM "steps" WHERE id = ?`, "2026-09-06").Scan(&n); err != nil {
		t.Fatalf("typed table query: %v", err)
	}
	if n != 1 {
		t.Fatalf("typed steps rows for 2026-09-06 = %d, want 1", n)
	}
}

func TestUpsertKeyedBatch_IsIdempotentAcrossReruns(t *testing.T) {
	db := newSeriesTestStore(t)
	row := []KeyedRow{{ID: "2026-09-06", Data: json.RawMessage(`{"calendarDate":"2026-09-06","totalSteps":8000}`)}}
	for i := 0; i < 3; i++ {
		if _, _, err := db.UpsertKeyedBatch("steps", row); err != nil {
			t.Fatalf("run %d: %v", i, err)
		}
	}
	n, err := db.CountResourceRows("steps")
	if err != nil {
		t.Fatalf("count: %v", err)
	}
	if n != 1 {
		t.Fatalf("three identical runs produced %d rows, want 1", n)
	}
}

func TestUpsertKeyedBatch_SkipsRowsWithNoKeyOrNoBody(t *testing.T) {
	db := newSeriesTestStore(t)
	stored, skipped, err := db.UpsertKeyedBatch("steps", []KeyedRow{
		{ID: "", Data: json.RawMessage(`{"totalSteps":1}`)},
		{ID: "2026-09-06", Data: nil},
		{ID: "2026-09-07", Data: json.RawMessage(`[1,2,3]`)}, // not an object
		{ID: "2026-09-08", Data: json.RawMessage(`{"calendarDate":"2026-09-08"}`)},
	})
	if err != nil {
		t.Fatalf("upsert: %v", err)
	}
	if stored != 1 || skipped != 3 {
		t.Fatalf("stored=%d skipped=%d, want 1/3: an unkeyed or unusable row must be skipped and counted, never stored under a blank key", stored, skipped)
	}
	var blank int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = 'steps' AND id = ''`).Scan(&blank); err != nil {
		t.Fatalf("blank key query: %v", err)
	}
	if blank != 0 {
		t.Fatalf("%d rows landed under a blank key", blank)
	}
}

